import AbstractController from '@adaptivestone/framework/modules/AbstractController.js';
import { BadGatewayError } from '@adaptivestone/framework/services/http/httpErrors.js';
import { HttpResponse } from '@adaptivestone/framework/services/http/responses.js';
import Mailer from '@adaptivestone/framework-module-email';
import { z } from 'zod';
// Generated by `npm run gen`; the `params:` schema below types
// `req.appInfo.params.email`, while raw `req.params.email` stays a string.
import type { GetEmailRequest } from './Email.routes.gen.ts';

class Email extends AbstractController {
  get routes() {
    return {
      get: {
        '/:email': {
          handler: this.getEmail,
          // A path param is an input like any other — validate it. A bad
          // address never reaches the mailer.
          params: z.object({ email: z.email() }),
        },
      },
    };
  }

  async getEmail(req: GetEmailRequest) {
    // Address shape is guaranteed by the route's `params:` schema above.
    // This route exists to exercise mail delivery; it is not production ready.
    const mail = new Mailer(
      req.appInfo.app,
      req.appInfo.params.email,
      req.query,
      req.appInfo.i18n,
    );
    // The SMTP server is an upstream service: when it is unreachable or
    // rejects the message, answer 502 Bad Gateway, not a generic 500. Throw
    // it; the framework renders it and logs it at `error` (a 5xx).
    const result = await mail.send('test@mail.com').catch((err: unknown) => {
      // Log the SMTP reason here: the client only sees the generic message.
      this.logger?.warn(`Mail delivery failed: ${String(err)}`);
      throw new BadGatewayError({
        code: 'MAIL_DELIVERY_FAILED',
        i18nKey: 'email.deliveryFailed',
        message: 'Mail delivery failed',
      });
    });
    return HttpResponse.json(200, { data: result });
  }

  static get middleware() {
    return new Map([['/{*splat}', []]]);
  }
}

export default Email;
